export function getPortraitAsset(faction: string, portraitId: number): any {
  const FACTION_PORTRAIT_COUNTS: Record<string, number> = {
    dwarf: 36,
    elf: 16,
    goblin: 16,
    human: 16,
    nightelf: 25,
    orc: 30
  };
  const maxCount = FACTION_PORTRAIT_COUNTS[faction] || 1;
  const localId = (portraitId % maxCount).toString().padStart(3, '0');
  const key = `${faction}_${localId}`;
  return PORTRAITS[key] || PORTRAITS['human_000'];
}
